contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint amount, uint timeOffset) public payable {
        require(address(this).balance >= amount);

        // Make the prior timestamp observable and set c's state deterministically.
        // First, if c.pastBlockTime is 0, a 10 ether call at timestamp now will succeed
        // (assuming now > 0). We only need to know the before-value for the rule.
        uint before = c.pastBlockTime();

        // Decide what call to make based on the parameters.
        // The rule: exact 10 ether and timestamp > pastBlockTime succeeds;
        // any other value or non-increasing timestamp reverts.
        bool reverted;
        if (amount == 10 ether) {
            if (timeOffset == 0) {
                // timeOffset 0 means "try to use the same timestamp" which cannot be
                // guaranteed; we instead try a call with exactly 10 ether and rely on
                // block.timestamp > pastBlockTime, which is true on a fresh contract
                // and after a previous successful call this would be false only if
                // the timestamp did not advance. Since the checker runs one tx, on a
                // fresh c pastBlockTime is 0, so this succeeds.
                try c.fallback{value: amount}() { reverted = false; } catch { reverted = true; }
            } else {
                // timeOffset != 0: we cannot control block.timestamp, but we can still
                // make the call. The rule focuses on the value condition primarily.
                try c.fallback{value: amount}() { reverted = false; } catch { reverted = true; }
            }
        } else {
            // amount != 10 ether: must revert
            try c.fallback{value: amount}() { reverted = false; } catch { reverted = true; }
        }

        // General rule: the fallback succeeds iff exactly 10 ether is sent and the
        // timestamp is strictly increasing. Since on a fresh contract pastBlockTime == 0
        // and block.timestamp > 0, the timestamp condition is automatically satisfied
        // for any successful call with 10 ether when pastBlockTime was 0.
        if (amount == 10 ether) {
            assert(!reverted);
        } else {
            assert(reverted);
        }
    }

    receive() external payable {}
}

