contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    bool private lock;

    receive() external payable {}

    function run(uint256 amount, uint256 initialPastBlockTime, uint256 initialBlockTime) public payable {
        require(initialPastBlockTime <= initialBlockTime);

        // Set up a concrete pastBlockTime using the first fallback call.
        // Only proceed if we can make a valid, successful setup call.
        if (initialBlockTime > initialPastBlockTime) {
            require(address(this).balance >= 10 ether);
            (bool setupOk, ) = address(c).call{value: 10 ether}("");
            if (setupOk) {
                // Now c.pastBlockTime() should equal initialBlockTime + 1 if setup modified it.
                // But we need a second call to test the rule; use a later timestamp.
                uint256 nextBlockTime = initialBlockTime + 1;
                // We cannot directly set block.timestamp; instead, we rely on actual timestamps and
                // make the property conditional on the actual setting. Since checkers may exploit
                // real timestamps, we drive with the given `amount` and rely on the contract's own
                // timestamp. To keep the rule general, we test that the amount requirement is exact.
                // The key rule: a call with amount != 10 ether must revert.
                bool reverted;
                if (amount != 10 ether) {
                    require(address(this).balance >= amount);
                    (bool ok, ) = address(c).call{value: amount}("");
                    reverted = !ok;
                    assert(reverted);
                } else {
                    // amount == 10 ether: the call may succeed or revert depending on timestamp,
                    // but if it succeeds, pastBlockTime must increase.
                    require(address(this).balance >= amount);
                    uint256 beforeVal = c.pastBlockTime();
                    (bool ok, ) = address(c).call{value: amount}("");
                    if (ok) {
                        assert(c.pastBlockTime() > beforeVal);
                    } else {
                        assert(c.pastBlockTime() == beforeVal);
                    }
                }
            } else {
                assert(true);
            }
        } else {
            assert(true);
        }
    }
}

