contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount, uint256 dt) public payable {
        require(address(this).balance >= amount, "not enough ether for the call");
        require(dt > 0, "dt must be positive");

        uint256 beforeBalance = address(c).balance;
        uint256 beforePast = c.pastBlockTime();

        bool timeAdvanceOk = true;
        if (beforePast > 0) {
            timeAdvanceOk = beforePast + dt > beforePast;
        }
        require(timeAdvanceOk, "timestamp delta must not overflow");

        bool reverted;
        try c.call{value: amount}("") {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterBalance = address(c).balance;
        uint256 afterPast = c.pastBlockTime();
        uint256 received = address(this).balance;

        if (amount == 10 ether && block.timestamp > beforePast) {
            assert(!reverted);
            assert(afterPast == block.timestamp + 1);
            assert(afterBalance >= beforeBalance - 10 ether + 10 ether || afterBalance == beforeBalance + 10 ether);
            assert(afterBalance + received >= beforeBalance);
        } else {
            assert(reverted);
            assert(afterPast == beforePast);
            assert(afterBalance == beforeBalance);
        }
    }

    receive() external payable {}
}

