        bool reverted;
        try c.fallback{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterTime = c.pastBlockTime();

        // General rule: the fallback reverts exactly when the current block.timestamp is not strictly greater
        // than the stored pastBlockTime at call time.
        // We approximate "current block.timestamp" using block.timestamp, which is the same in test and call.
