        // If it reverted, pastBlockTime must be unchanged from beforeTime.
        assert(
            (reverted == (block.timestamp <= beforeTime)) &&
            (
                (reverted && afterTime == beforeTime) ||
                (!reverted && afterTime == block.timestamp + 1)
            )
        );
    }

    receive() external payable {}
}

